-- ========================================================
-- مركز الطالبة - خدمة حساب المعدل
-- مخطط قاعدة البيانات (نفّذي هذا الملف كامل في Supabase SQL Editor)
-- ========================================================

-- 1) ملفات المستخدمين (تُنشأ تلقائيًا مع كل حساب جديد) + الدور (طالبة/أدمن)
create table if not exists public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  email text,
  role text not null default 'student' check (role in ('student','admin')),
  created_at timestamptz not null default now()
);

alter table public.profiles enable row level security;

create policy "profiles_select_own_or_admin"
  on public.profiles for select
  using (
    auth.uid() = id
    or exists (select 1 from public.profiles p where p.id = auth.uid() and p.role = 'admin')
  );

create policy "profiles_update_own"
  on public.profiles for update
  using (auth.uid() = id);

-- إنشاء صف profile تلقائيًا عند تسجيل أي مستخدم جديد
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer set search_path = public
as $$
begin
  insert into public.profiles (id, email) values (new.id, new.email);
  return new;
end;
$$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute procedure public.handle_new_user();

-- 2) المقررات (البيانات اللي تظهر بجداول حساب المعدل - تقدر الأدمن تعدلها)
create table if not exists public.courses (
  id bigint generated always as identity primary key,
  group_type text not null check (group_type in ('year1_plan','track')),
  group_key text not null,       -- 'A' / 'B' لسنة أولى، أو chemistry/physics/commercial/literary للتخصصات
  semester smallint not null check (semester between 1 and 6),
  code text not null,
  hours smallint not null check (hours > 0),
  sort_order smallint not null default 1,
  created_at timestamptz not null default now(),
  unique (group_type, group_key, semester, code)
);

create index if not exists courses_lookup_idx
  on public.courses (group_type, group_key, semester, sort_order);

alter table public.courses enable row level security;

create policy "courses_select_all"
  on public.courses for select
  using (true);

create policy "courses_admin_write"
  on public.courses for all
  using (exists (select 1 from public.profiles p where p.id = auth.uid() and p.role = 'admin'))
  with check (exists (select 1 from public.profiles p where p.id = auth.uid() and p.role = 'admin'));

-- 3) المعدلات المحفوظة لكل طالبة صاحبة حساب (بدل/بالإضافة للحفظ المؤقت بالمتصفح)
create table if not exists public.gpa_records (
  user_id uuid primary key references auth.users(id) on delete cascade,
  plan text,
  track text,
  grades jsonb not null default '{}'::jsonb,
  updated_at timestamptz not null default now()
);

alter table public.gpa_records enable row level security;

create policy "gpa_records_owner_only"
  on public.gpa_records for all
  using (auth.uid() = user_id)
  with check (auth.uid() = user_id);

